#!/usr/bin/env python3
# 加密的camera_cmd模块
import sys
import os
import base64
import types

_script_dir = os.path.dirname(os.path.abspath(__file__))
if _script_dir not in sys.path:
  sys.path.insert(0, _script_dir)

ENCODED_SOURCE = '''

'''

def _decode_and_execute():
  """解码并执行源码，返回模块的全局命名空间"""
  try:
    source_code = base64.b64decode(ENCODED_SOURCE).decode('utf-8')
    code = compile(source_code, 'camera_cmd.py', 'exec')
    
    import builtins
    globals_dict = {
      '__name__': 'gen_controller_sdk_python.camera_cmd',
      '__file__': __file__,
      '__package__': 'gen_controller_sdk_python',
      '__builtins__': builtins,
    }
    
    exec(code, globals_dict)
    return globals_dict
  except Exception as e:
    print(f"解码错误: {e}")
    import traceback
    traceback.print_exc()
    raise

# 解码并获取原始模块的全局命名空间
_original_globals = _decode_and_execute()

# 导出原始模块的所有非私有符号
for name, value in _original_globals.items():
  if not name.startswith('_') and name not in globals():
    globals()[name] = value

# 定义main函数，用于脚本执行
def main():
  """主函数 - 用于脚本执行"""
  try:
    if 'main' in _original_globals:
      sys.argv[0] = 'camera_cmd.py'
      _original_globals['main']()
    else:
      print("错误: 找不到main函数")
      sys.exit(1)
  except Exception as e:
    print(f"执行错误: {e}")
    import traceback
    traceback.print_exc()
    sys.exit(1)

if __name__ == '__main__':
  main()
